/*
 * ui — design tokens, using shadcn/ui's names so the components sit alongside any shadcn component.
 *
 * Light is the default. Dark applies with `.dark` or `[data-theme="dark"]` on an ancestor, usually <html>.
 * Every text pair passes WCAG AA in both themes.
 *
 * Change a value here and every component follows. One knob for corners: --radius.
 */
@import "@fontsource-variable/inter/wght.css";
@import "@fontsource/apfel-grotezk/400.css";
@import "@fontsource/apfel-grotezk/700.css";

@custom-variant dark (&:where(.dark, .dark *, [data-theme="dark"], [data-theme="dark"] *));

:root {
  --radius: 12px;

  --background: #fbfaf9;
  --foreground: #121212;
  --card: #ffffff;
  --card-foreground: #121212;
  --popover: #ffffff;
  --popover-foreground: #121212;

  /* Button fill. White text on it is 4.6:1. */
  --primary: #dd3400;
  --primary-hover: #c62e00;
  --primary-foreground: #ffffff;

  /* The brand orange: current position, selection, marks. Not under text. */
  --brand: #ff3e00;
  --brand-soft: #fff0ea;
  /* The brand orange dark enough for text: an active link, a current step. */
  --brand-strong: #c62e00;

  --secondary: #f4f2ee;
  --secondary-foreground: #121212;
  --muted: #f4f2ee;
  --muted-foreground: #6e6e6d;
  --accent: #eeebe6;
  --accent-foreground: #121212;
  --accent-pressed: #e6e2dc;

  /* soft: between foreground and muted. faint: disabled text and decorative marks only; it is below AA. */
  --soft-foreground: #3b3a37;
  --faint-foreground: #a5a29c;

  /* Reserved for errors and failures. Nothing else may use this hue. */
  --destructive: oklch(0.52 0.15 20);
  --destructive-soft: oklch(0.95 0.03 20);
  --success: oklch(0.5 0.09 155);
  --success-soft: oklch(0.95 0.03 155);
  --warning: oklch(0.52 0.1 78);
  --warning-soft: oklch(0.95 0.04 85);
  --info: oklch(0.5 0.09 255);
  --info-soft: oklch(0.95 0.025 255);

  --border: #e3dfd8;
  /* Input borders and the off switch track: 3:1 against the page. */
  --input: #8a8782;
  --ring: #121212;

  /* Elevation by tone and soft shadow, never a 1px ring: the brief separates without borders. */
  --shadow-raised: 0 1px 2px rgb(18 18 18 / 0.05), 0 4px 12px -2px rgb(18 18 18 / 0.06);
  --shadow-float: 0 0 0 1px rgb(18 18 18 / 0.06), 0 8px 24px -6px rgb(18 18 18 / 0.14), 0 2px 6px rgb(18 18 18 / 0.05);
  --shadow-shell: none;
}

.dark,
[data-theme="dark"] {
  color-scheme: dark;
  --background: #0e0e0d;
  --foreground: #f2f1ef;
  --card: #22221f;
  --card-foreground: #f2f1ef;
  --popover: #1f1f1c;
  --popover-foreground: #f2f1ef;

  --primary: #dd3400;
  --primary-hover: #c62e00;
  --primary-foreground: #ffffff;
  --brand: #ff5a1f;
  --brand-soft: #2a170f;
  --brand-strong: #ff7a45;

  --secondary: #1a1a18;
  --secondary-foreground: #f2f1ef;
  --muted: #1a1a18;
  --muted-foreground: #8d8c8a;
  --accent: #23231f;
  --accent-foreground: #f2f1ef;
  --accent-pressed: #2b2b27;
  --soft-foreground: #c9c7c3;
  --faint-foreground: #64625e;

  --destructive: oklch(0.72 0.13 22);
  --destructive-soft: oklch(0.26 0.04 22);
  --success: oklch(0.74 0.1 155);
  --success-soft: oklch(0.25 0.035 155);
  --warning: oklch(0.8 0.1 82);
  --warning-soft: oklch(0.26 0.035 82);
  --info: oklch(0.74 0.08 255);
  --info-soft: oklch(0.25 0.03 255);

  --border: #2a2a27;
  --input: #6b6965;
  --ring: #f2f1ef;

  --shadow-raised: 0 1px 2px rgb(0 0 0 / 0.4), 0 4px 12px -2px rgb(0 0 0 / 0.35);
  --shadow-float: 0 0 0 1px rgb(255 255 255 / 0.07), 0 12px 32px -8px rgb(0 0 0 / 0.6);
  --shadow-shell: none;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-hover);
  --color-primary-foreground: var(--primary-foreground);
  --color-brand: var(--brand);
  --color-brand-soft: var(--brand-soft);
  --color-brand-strong: var(--brand-strong);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-accent-pressed: var(--accent-pressed);
  --color-soft-foreground: var(--soft-foreground);
  --color-faint-foreground: var(--faint-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-soft: var(--destructive-soft);
  --color-success: var(--success);
  --color-success-soft: var(--success-soft);
  --color-warning: var(--warning);
  --color-warning-soft: var(--warning-soft);
  --color-info: var(--info);
  --color-info-soft: var(--info-soft);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* shadcn's scale, derived from one knob. At 12px: xs 6, sm 8, md 10, lg 12, xl 16, 2xl 20. */
  --radius-xs: calc(var(--radius) - 6px);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);

  --shadow-raised: var(--shadow-raised);
  --shadow-float: var(--shadow-float);
  --shadow-shell: var(--shadow-shell);
}

@theme {
  --font-sans: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Apfel Grotezk", "Inter Variable", ui-sans-serif, sans-serif;

  --ease-out: cubic-bezier(0.23, 1, 0.32, 1);
  --ease-in: cubic-bezier(0.55, 0, 1, 0.45);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-drawer: cubic-bezier(0.32, 0.72, 0, 1);

  /* Type scale. At most four of these on one screen. */
  --text-micro: 0.75rem;
  --text-micro--line-height: 1.4;
  --text-small: 0.8125rem;
  --text-small--line-height: 1.45;
  --text-body: 0.9375rem;
  --text-body--line-height: 1.55;
  --text-lead: 1.0625rem;
  --text-lead--line-height: 1.5;
  --text-title: 1.25rem;
  --text-title--line-height: 1.2;
  --text-display: 2.5rem;
  --text-display--line-height: 1.05;
}

@layer base {
  html {
    color-scheme: light;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-feature-settings: "cv11", "ss03";
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    -webkit-tap-highlight-color: transparent;
  }
  ::selection {
    background: color-mix(in oklab, var(--brand) 22%, transparent);
  }
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  button:not(:disabled),
  [role="button"]:not([aria-disabled="true"]) {
    cursor: pointer;
  }
}

/* Numbers that change or line up. */
@utility tnum {
  font-variant-numeric: tabular-nums;
}

/* Press feedback for anything pressable. Disabled never scales; reduced motion never scales. */
@utility pressable {
  transition-property: scale, background-color, color, box-shadow, opacity;
  transition-duration: 150ms;
  transition-timing-function: var(--ease-out);
  &:not(:disabled):active {
    scale: 0.97;
  }
  @media (prefers-reduced-motion: reduce) {
    &:not(:disabled):active {
      scale: 1;
    }
  }
}
